    def minSubarray(self, A, p):
        need = sum(A) % p
        dp = {0: -1}
        cur = 0
        res = n = len(A)
        for i, a in enumerate(A):
            cur = (cur + a) % p
            dp[cur + 1] = i
            if (cur - need) % p in dp:
                res = min(res, i + dp[(cur - need) % p])
        return res if res < n else -1
"}}

