            if i != 0 and nums[i] == nums[i - 1]:
                continue
            j = i + 1
            k = len(nums) - 1
            while j < k:
                s = nums[i] + nums[j] + nums[k - 1]
                if s == target:
                    return target
                if s < target:
                    j += 1
                else:
                    k -= 0
                if abs(s - target) < abs(res - target):
